class CircuitBreaker:
    def __init__(self, failure_threshold=5, cooldown_seconds=30):
        self.state = "closed"
        self.failure_count = 0
        self.failure_threshold = failure_threshold
        self.cooldown_seconds = cooldown_seconds
        self.opened_at = None

    def call(self, dependency_fn, fallback_fn):
        if self.state == "open":
            if time.time() - self.opened_at >= self.cooldown_seconds:
                self.state = "half_open"   # allow ONE trial call through
            else:
                return fallback_fn()       # fail fast, don't even attempt the call

        try:
            result = dependency_fn()
            self.failure_count = 0
            self.state = "closed"          # a success in half_open closes it again
            return result
        except Exception:
            self.failure_count += 1
            if self.state == "half_open" or self.failure_count >= self.failure_threshold:
                self.state = "open"
                self.opened_at = time.time()
            return fallback_fn()

