def get_shipping_rate(order):
    if breaker.state == "open":
        return DEFAULT_SHIPPING_RATE   # fail fast -- skip the real call ENTIRELY

    try:
        result = call_shipping_api(order, timeout=15)
        breaker.record_success()
        return result
    except Exception:
        breaker.record_failure()
        raise

