exercises.solutionCode:
work_queue = queue.Queue(maxsize=5000)   # bounded -- caps memory AND provides backpressure

def producer():
    while True:
        event = generate_event()
        work_queue.put(event, block=True)  # BLOCKS once the queue hits 5000 items,
                                             # naturally slowing the producer down
                                             # to match the consumer's real throughput

def consumer():
    while True:
        event = work_queue.get()
        slow_process(event)
